package app.mambo.next;
import android.content.*;import android.media.*;import android.os.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
public final class ClickAudio {
 private final Context context;private final Data data;private final SoundPool pool;private final Handler ui=new Handler(Looper.getMainLooper());private final ExecutorService loader=Executors.newSingleThreadExecutor();private final Map<String,Integer> ids=new HashMap<>();private final Set<Integer> ready=new HashSet<>();private final Set<Integer> failed=new HashSet<>();private String pending;private boolean closed;private int stream;
 public ClickAudio(Context c,Data d){context=c.getApplicationContext();data=d;pool=new SoundPool.Builder().setMaxStreams(1).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build()).build();pool.setOnLoadCompleteListener((p,id,status)->{if(closed)return;if(status==0){ready.add(id);if(pending!=null&&ids.get(pending)!=null&&ids.get(pending)==id){pending=null;playId(id);}}else {failed.add(id);data.log("Звук: не удалось загрузить PCM-сэмпл");}});
  loader.execute(()->{for(String name:new String[]{"meow-0","meow-1","meow-2","meow-3","meow-4","horse","mambo"}){try{File file=new File(context.getCacheDir(),name+".wav");try(InputStream in=context.getAssets().open("audio/"+name+".wav");OutputStream out=new FileOutputStream(file)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}ui.post(()->{if(!closed){int id=pool.load(file.getAbsolutePath(),1);ids.put(name,id);if(id==0){failed.add(id);data.log("Звук: SoundPool отклонил файл");}}});}catch(Exception e){data.log("Звук: файл недоступен");}}});
 }
 public void play(int page,boolean preview){if(closed)return;String bank=data.s("sound","meow");if(bank.equals("mute")){if(preview)toast("Звук выключен в настройках");return;}AudioManager audio=(AudioManager)context.getSystemService(Context.AUDIO_SERVICE);if(audio.getStreamVolume(AudioManager.STREAM_MUSIC)==0){if(preview)toast("Увеличь громкость мультимедиа на телефоне");return;}String name=bank;if(bank.equals("meow")){int sample=data.n("meowSample",0);name="meow-"+(sample==0?page%5:sample-1);}Integer id=ids.get(name);if(id!=null&&failed.contains(id)){if(preview)toast("Не удалось загрузить звук. Посмотри журнал событий.");return;}if(id==null||!ready.contains(id)){pending=name;if(preview)toast("Звук загружается…");return;}pending=null;playId(id);}
 private void playId(int id){if(stream!=0)pool.stop(stream);float volume=data.n("volume",75)/100f;stream=pool.play(id,volume,volume,1,0,1f);if(stream==0)data.log("Звук: проигрывание не началось");}
 private void toast(String s){android.widget.Toast.makeText(context,s,android.widget.Toast.LENGTH_SHORT).show();}
 public void close(){closed=true;pending=null;loader.shutdownNow();pool.release();}
}
